INSERT INTO `platform_alert_event` VALUES (339, '31dddb93d5ba5d00', NULL, 'Watchdog', 'none', 'firing', 'ca461aeb058ccbbe', '{\"severity\": \"none\", \"alertname\": \"Watchdog\", \"prometheus\": \"monitor/platform-kps-kube-promethe-prometheus\", \"cluster_name\": \"coding-cluster\"}', '{\"summary\": \"An alert that should always be firing to certify that Alertmanager is working properly.\", \"description\": \"This is an alert meant to ensure that the entire alerting pipeline is functional.\\nThis alert is always firing, therefore it should always be firing in Alertmanager\\nand always fire against a receiver. There are integrations with various notification\\nmechanisms that send a notification when this alert is not firing. For example the\\n\\\"DeadMansSnitch\\\" integration in PagerDuty.\\n\", \"runbook_url\": \"https://runbooks.prometheus-operator.dev/runbooks/general/watchdog\"}', '2026-10-30 10:06:34.567', NULL, '2026-11-01 11:12:33.749');
