ction\"}]}],\"extract\":{\"metadata\":[\"k8s.namespace.name\",\"k8s.pod.name\",\"k8s.deployment.name\",\"k8s.statefulset.name\",\"k8s.daemonset.name\",\"k8s.job.name\",\"k8s.node.name\"]}},\"batch\":{\"send_batch_size\":8192,\"timeout\":\"5s\"},\"memory_limiter\":{\"limit_percentage\":80,\"check_interval\":\"1s\",\"spike_limit_percentage\":20}},\"exporters\":{\"otlp/tempo\":{\"endpoint\":\"${env:TEMPO_ENDPOINT}\",\"tls\":{\"insecure\":true}},\"prometheus\":{\"resource_to_telemetry_conversion\":{\"enabled\":true},\"endpoint\":\"0.0.0.0:8889\"},\"elasticsearch\":{\"endpoints\":[\"${env:ES_ENDPOINT}\"],\"tls\":{\"insecure_skip_verify\":true},\"password\":\"${env:ES_PASSWORD}\",\"logstash_format\":{\"date_format\":\"%Y.%m.%d\",\"enabled\":true,\"prefix_separator\":\"-\"},\"logs_index\":\"otel-logs\",\"user\":\"${env:ES_USERNAME}\",\"mapping\":{\"allowed_modes\":[\"none\"]}}},\"service\":{\"pipelines\":{\"traces\":{\"receivers\":[\"otlp\"],\"processors\":[\"memory_limiter\",\"resource\",\"k8sattributes\",\"batch\"],\"exporters\":[\"otlp/tempo\"]},\"metrics\":{\"receivers\":[\"otlp\"],\"processors\":[\"memory_limiter\",\"resource\",\"k8sattributes\",\"batch\"],\"exporters\":[\"prometheus\"]},\"logs\":{\"receivers\":[\"otlp\"],\"processors\":[\"memory_limiter\",\"resource\",\"k8sattributes\",\"batch\"],\"exporters\":[\"elasticsearch\"]}}}}}},{\"metadata\":{\"name\":\"platform-otel-sidecar\",\"namespace\":\"monitor\"},\"apiVersion\":\"opentelemetry.io/v1beta1\",\"kind\":\"OpenTelemetryCollector\",\"spec\":{\"mode\":\"sidecar\",\"volumeMounts\":[{\"readOnly\":true,\"name\":\"platform-otel-logs\",\"mountPath\":\"/var/log/app\"}],\"env\":[{\"name\":\"K8S_POD_NAME\",\"valueFrom\":{\"fieldRef\":{\"fieldPath\":\"metadata.name\"}}},{\"name\":\"K8S_NAMESPACE\",\"valueFrom\":{\"fieldRef\":{\"fieldPath\":\"metadata.namespace\"}}},{\"name\":\"K8S_POD_UID\",\"valueFrom\":{\"fieldRef\":{\"fieldPath\":\"metadata.uid\"}}},{\"name\":\"OTEL_FILELOG_INCLUDE\",\"valueFrom\":{\"fieldRef\":{\"f