-- Table structure for platform_alert_delivery
-- ----------------------------
DROP TABLE IF EXISTS `platform_alert_delivery`;
CREATE TABLE `platform_alert_delivery`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '追加型日志表，同 platform_audit_log',
  `event_id` bigint NOT NULL,
  `channel_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `alert_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '投递时的告警状态 firing/resolved',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PENDING/SENT/FAILED',
  `attempts` int NOT NULL DEFAULT 0,
  `last_error` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `sent_at` datetime(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_delivery_once`(`event_id` ASC, `channel_code` ASC, `alert_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '告警投递记录' ROW_FORMAT = Dynamic;

