-- ----------------------------
-- Table structure for platform_alert_event
-- ----------------------------
DROP TABLE IF EXISTS `platform_alert_event`;
CREATE TABLE `platform_alert_event`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增（非 ULID）—— 理由同 platform_audit_log：追加型日志表',
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `namespace` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来自 labels.namespace，规则作者自报；归属靠查询时 join 分配表',
  `alertname` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `severity` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'labels.severity',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'firing | resolved',
  `fingerprint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Alertmanager 给，标签集的哈希',
  `labels` json NULL,
  `annotations` json NULL,
  `starts_at` datetime(3) NOT NULL COMMENT '本次 firing 会话开始时刻',
  `ends_at` datetime(3) NULL DEFAULT NULL COMMENT 'resolved 才有',
  `received_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_alert_episode`(`cluster_id` ASC, `fingerprint` ASC, `starts_at` ASC) USING BTREE,
  INDEX `idx_alert_ns_time`(`cluster_id` ASC, `namespace` ASC, `starts_at` ASC) USING BTREE,
  INDEX `idx_alert_time`(`cluster_id` ASC, `starts_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 384 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '告警事件（一次 firing 会话一行）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_alert_event
-- ----------------------------

-- ----------------------------
-- Table structure for platform_application
-- ----------------------------
DROP TABLE IF EXISTS `platform_application`;
CREATE TABLE `platform_application`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '归属租户；创建时必填，列可空只为兼容旧数据与管理员视图',
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `namespace` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `slug` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'K8s 对象名前缀',
  `display_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT / DEPLOYING / READY / FAILED / DELETING',
  `spec_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `current_revision` int NOT NULL DEFAULT 0,
  `created_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime NULL DEFAULT NULL,
  `active_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS (if((`deleted_at` is null),concat(`cluster_id`,_utf8mb4'/',`namespace`,_utf8mb4'/',`name`),NULL)) STORED NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_app_active`(`active_key` ASC) USING BTREE,
  INDEX `idx_app_tenant`(`tenant_id` ASC, `cluster_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '应用（画布）台账' ROW_FORMAT = Dynamic;

