-- Table structure for platform_application_operation
-- ----------------------------
DROP TABLE IF EXISTS `platform_application_operation`;
CREATE TABLE `platform_application_operation`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `revision` int NOT NULL,
  `action` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'DEPLOY / UPGRADE / DELETE / RETRY',
