  `current_step` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PRECHECK' COMMENT 'PRECHECK / RENDER / CONFLICT / APPLY / PRUNE / HEALTH / DONE',
  `node_states_json` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '{节点key: 状态}',
  `message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `started_at` datetime NOT NULL,
