  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_app_op_active`(`app_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '应用的部署操作（阶段机）' ROW_FORMAT = Dynamic;

