-- ----------------------------
-- Table structure for platform_application_revision
-- ----------------------------
DROP TABLE IF EXISTS `platform_application_revision`;
CREATE TABLE `platform_application_revision`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `revision` int NOT NULL,
  `spec_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
