-- Table structure for platform_audit_log
-- ----------------------------
DROP TABLE IF EXISTS `platform_audit_log`;
CREATE TABLE `platform_audit_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `occurred_at` datetime(3) NOT NULL COMMENT '发生时刻（毫秒）',
  `actor_username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '操作者账号；取不到身份时记字面量 unknown（不记 NULL）',
  `actor_display_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '冗余存：账号改名/删除后记录仍可读',
  `tenant_id` varchar(26) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '被操作的租户（代操作时是目标租户；平台侧无租户操作为 NULL）',
  `cluster_id` varchar(26) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `namespace` varchar(63) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `action` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '写操作=动作码 <resource>:<verb>；DENIED=被拒的权限码。语义随 result 变',
  `target_name` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '目标对象名；DENIED 为空（拒绝发生在方法调用前）',
  `result` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'SUCCESS / FAILED / DENIED',
  `error_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'FAILED 的业务码',
  `error_msg` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'FAILED 的业务 msg',
  `http_method` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '仅 DENIED 有值',
  `request_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '仅 DENIED 有值',
  `client_ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '兼容 IPv6',
  `user_agent` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '安全排查用',
  `duration_ms` int NULL DEFAULT NULL COMMENT '耗时；DENIED 为 NULL',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_occurred`(`occurred_at` ASC, `id` ASC) USING BTREE,
  INDEX `idx_actor`(`actor_username` ASC, `occurred_at` ASC) USING BTREE,
  INDEX `idx_cluster_ns`(`cluster_id` ASC, `namespace` ASC, `occurred_at` ASC) USING BTREE,
  INDEX `idx_result`(`result` ASC, `occurred_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 767 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '平台审计日志（写操作 + 403 被拒请求）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_audit_log
-- ----------------------------

-- ----------------------------
-- Table structure for platform_component_operation
-- ----------------------------
DROP TABLE IF EXISTS `platform_component_operation`;
CREATE TABLE `platform_component_operation`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `component_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `action` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'INSTALL / UPGRADE',
  `profile` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '本次使用的画像（MANAGEMENT/BUSINESS）',
  `from_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `to_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '目标 chart 版本',
  `release_names` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '本次涉及的 release 名（JSON 数组）',
  `values_snapshot` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '最终合并后的 values（升级时复用）',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PENDING/RUNNING/SUCCESS/FAILED/UNKNOWN',
  `message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `log_tail` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'helm 输出去敏后的尾部',
  `operator` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `started_at` datetime NOT NULL,
  `finished_at` datetime NULL DEFAULT NULL,
  `running_lock` varchar(130) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS (if((`status` in (_utf8mb4'PENDING',_utf8mb4'RUNNING')),concat(`cluster_id`,_utf8mb4'|',`component_code`),NULL)) STORED NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_component_op_running`(`running_lock` ASC) USING BTREE,
  INDEX `idx_component_op_cluster_component`(`cluster_id` ASC, `component_code` ASC, `started_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '组件安装/升级操作记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_component_operation
-- ----------------------------

-- ----------------------------
-- Table structure for platform_credential
-- ----------------------------
DROP TABLE IF EXISTS `platform_credential`;
CREATE TABLE `platform_credential`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ULIDGenerator（16 位 hex），同库内其它表惯例',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '显示名，全局唯一',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'GIT / REGISTRY（v1 仅此两类）',
  `endpoint` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'host 基址：GIT=https://gitlab.example.com，REGISTRY=harbor.example.com',
  `auth_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'BASIC（v1 唯一实现）；加 SSH 时在此扩展，不动表',
  `secret_encrypted` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AES 密文（含 v1: 前缀），明文是认证字段 JSON。v1 恒非空（BASIC 必填）；可空是为将来 NONE 型（匿名）留位',
  `secret_fingerprint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'SHA-256(认证字段 JSON) 前 16 hex；用于区分「改了凭据」与「只改了描述」',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '0=停用：仍在列表里，但消费方不应选它',
  `last_verified_at` datetime NULL DEFAULT NULL COMMENT '上次**测试通过**的时刻；失败不改它',
  `last_verify_error` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上次测试的失败原因；成功则置 NULL',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `usable_by_pipelines` tinyint NOT NULL DEFAULT 0 COMMENT '1=允许租户在流水线的 git/推送节点里引用这条连接；默认 0（关）',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '归属租户；NULL = 平台级（现有全局凭据语义）',
  `source` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'MANUAL' COMMENT 'MANUAL / HARBOR（Harbor 自动维护，凭据页只读）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_name`(`name` ASC) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_credential_tenant`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '平台级凭据（git / registry 连接）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_credential
-- ----------------------------

-- ----------------------------
-- Table structure for platform_middleware_instance
-- ----------------------------
DROP TABLE IF EXISTS `platform_middleware_instance`;
CREATE TABLE `platform_middleware_instance`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `namespace` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'SINGLE/CLUSTER/SENTINEL/STANDALONE/HA',
  `name` varchar(63) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'K8s 对象名（平台生成 mw-<code>-<8hex>）',
  `display_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `spec_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '表单规格（不含凭据）',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'CREATING/READY/DEGRADED/FAILED/DELETING',
  `message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime NULL DEFAULT NULL,
  `app_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建它的应用；空 = 中间件商店直接建的',
  `app_node_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '应用里的节点 key',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mwi_name`(`cluster_id` ASC, `namespace` ASC, `name` ASC) USING BTREE,
  INDEX `idx_mwi_code`(`cluster_id` ASC, `code` ASC, `deleted_at` ASC) USING BTREE,
  INDEX `idx_mwi_tenant`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '中间件实例' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_middleware_instance
-- ----------------------------

-- ----------------------------
-- Table structure for platform_middleware_operation
-- ----------------------------
DROP TABLE IF EXISTS `platform_middleware_operation`;
CREATE TABLE `platform_middleware_operation`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `action` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'CREATE/DELETE/SCALE/UPGRADE',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'PENDING/RUNNING/SUCCESS/FAILED/UNKNOWN',
  `message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `log_tail` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `operator` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `started_at` datetime NOT NULL,
  `finished_at` datetime NULL DEFAULT NULL,
  `running_lock` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS (if((`status` in (_utf8mb4'PENDING',_utf8mb4'RUNNING')),concat(`cluster_id`,_utf8mb4'|',`instance_id`),NULL)) STORED NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mwo_running`(`running_lock` ASC) USING BTREE,
  INDEX `idx_mwo_instance`(`instance_id` ASC, `started_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '中间件实例操作' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_middleware_operation
-- ----------------------------

-- ----------------------------
-- Table structure for platform_middleware_operator
-- ----------------------------
DROP TABLE IF EXISTS `platform_middleware_operator`;
CREATE TABLE `platform_middleware_operator`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'mysql/redis/kafka/elasticsearch/postgresql/rabbitmq/nacos',
  `chart_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'NOT_INSTALLED/INSTALLING/READY/FAILED/DEGRADED',
  `message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `installed_at` datetime NULL DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mwo_cluster_code`(`cluster_id` ASC, `code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '中间件 Operator 安装状态' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_middleware_operator
-- ----------------------------

-- ----------------------------
-- Table structure for platform_notification_channel
-- ----------------------------
DROP TABLE IF EXISTS `platform_notification_channel`;
CREATE TABLE `platform_notification_channel`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '写进 label 的值；K8s label 合法；全局唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'EMAIL（本轮唯一）',
  `config` json NULL COMMENT '按类型的连接配置；敏感字段加密后存字符串',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'NULL=全局；非空=该租户专用',
  `is_default` tinyint NOT NULL DEFAULT 0,
  `enabled` tinyint NOT NULL DEFAULT 1,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_notify_channel_code`(`code` ASC) USING BTREE,
  INDEX `idx_notify_channel_tenant`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '通知方式（渠道）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_notification_channel
-- ----------------------------

-- ----------------------------
-- Table structure for platform_object_bucket
-- ----------------------------
DROP TABLE IF EXISTS `platform_object_bucket`;
CREATE TABLE `platform_object_bucket`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `bucket` varchar(63) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'S3 桶名（平台生成 t-<租户短码>-<名字>）',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '归属租户',
  `display_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ACTIVE / DELETING / DELETED',
  `created_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime NULL DEFAULT NULL,
  `active_key` varchar(140) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci GENERATED ALWAYS AS (if((`deleted_at` is null),concat(`cluster_id`,_utf8mb4'|',`bucket`),NULL)) STORED NULL,
  `quota_bytes` bigint NULL DEFAULT NULL COMMENT '桶容量上限（字节）；NULL = 不限。同时写进 SeaweedFS 的每桶 quota',
  `anonymous_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=该桶允许匿名读（S3 的 anonymous 身份里有 Read:<桶>）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pob_active`(`active_key` ASC) USING BTREE,
  INDEX `idx_pob_tenant`(`cluster_id` ASC, `tenant_id` ASC, `deleted_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '对象存储桶台账' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_object_bucket
-- ----------------------------

-- ----------------------------
-- Table structure for platform_object_credential
-- ----------------------------
DROP TABLE IF EXISTS `platform_object_credential`;
CREATE TABLE `platform_object_credential`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `bucket_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'platform_object_bucket.id',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `identity_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'SeaweedFS S3 配置里的 identity 名',
  `access_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '可展示；secretKey 不落库',
  `secret_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'K8s Secret 名（platform-storage），存 access_key/secret_key',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ACTIVE / REVOKED',
  `created_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `revoked_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_poc_bucket`(`bucket_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_poc_tenant`(`cluster_id` ASC, `tenant_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '对象存储访问凭据台账（密钥本体在 K8s Secret）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_object_credential
-- ----------------------------

-- ----------------------------
-- Table structure for platform_object_quota
-- ----------------------------
DROP TABLE IF EXISTS `platform_object_quota`;
CREATE TABLE `platform_object_quota`  (
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `max_buckets` int NOT NULL COMMENT '该租户在本集群可拥有的桶数上限',
  `updated_by` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`cluster_id`, `tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '对象存储按租户的桶配额' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_object_quota
-- ----------------------------

-- ----------------------------
-- Table structure for platform_permission
-- ----------------------------
DROP TABLE IF EXISTS `platform_permission`;
CREATE TABLE `platform_permission`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `domain` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '权限域：K8S / Page / API ',
  `resource` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源：Deployment... / Page / API',
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '动作：create/update/delete/view/execute',
  `code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一标识',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '软删除时间，NULL = 未删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_code`(`code` ASC) USING BTREE,
  INDEX `idx_domain_resource_action`(`domain` ASC, `resource` ASC, `action` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_permission
-- ----------------------------

-- ----------------------------
-- Table structure for platform_pipeline
-- ----------------------------
DROP TABLE IF EXISTS `platform_pipeline`;
CREATE TABLE `platform_pipeline`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ULIDGenerator',
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `namespace` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '命名空间级资源 —— 跟 Deployment/Service 一样',
  `name` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '同命名空间内唯一（靠下面那条唯一索引，本仓不加外键）',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `canvas_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '画布：节点 + 连线。**流水线的唯一真相源** —— 集群里不留 Pipeline 对象',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pipeline`(`cluster_id` ASC, `namespace` ASC, `name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流水线（画布 JSON 是唯一真相源）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_pipeline
-- ----------------------------

-- ----------------------------
-- Table structure for platform_pipeline_run
-- ----------------------------
DROP TABLE IF EXISTS `platform_pipeline_run`;
CREATE TABLE `platform_pipeline_run`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `pipeline_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `namespace` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `canvas_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '触发那一刻的画布 JSON —— 历史运行详情画它，不是画今天的流水线',
  `run_name` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '集群里的 PipelineRun 名，**由平台先生成** —— 归档幂等键',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'RUNNING / SUCCEEDED / FAILED / CANCELLED / TIMEOUT',
  `reason` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因：优先是**失败那个节点的原话**（Tekton TaskRun 的 message），取不到才退回顶层 condition 的 reason',
  `triggered_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `start_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `completion_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `steps_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '每个节点的状态与耗时',
  `run_yaml` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '归档那一刻抓下来的 PipelineRun YAML（对象随后被删，这是「当年跑的是什么」的唯一存续形式）',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `parent_run_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '重试来源运行 id；NULL = 首跑',
  `attempt_no` int NOT NULL DEFAULT 1 COMMENT '同一条重试链的第几次尝试',
  `retry_from_node` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用户点的那个断点（画布节点 id）',
  `masked_nodes_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '本次运行屏蔽的节点（JSON 数组，闭包展开后）',
  `reused_nodes_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '重试时沿用的节点（JSON 数组，父运行里已成功）',
  `workspace_pvc` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '本次运行（链）使用的共享工作区 PVC 名',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_run_name`(`run_name` ASC) USING BTREE,
  INDEX `idx_pipeline`(`pipeline_id` ASC) USING BTREE,
  INDEX `idx_completion`(`completion_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流水线运行记录（集群对象归档后删掉，本表是运行历史的唯一来源）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_pipeline_run
-- ----------------------------

-- ----------------------------
-- Table structure for platform_pipeline_run_log
-- ----------------------------
DROP TABLE IF EXISTS `platform_pipeline_run_log`;
CREATE TABLE `platform_pipeline_run_log`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `run_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `node_name` varchar(253) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '画布上的节点 id（= Tekton task 名）',
  `content` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '**单步上限 1 MB**，超出截断',
  `truncated` tinyint NOT NULL DEFAULT 0,
  `size_bytes` int NOT NULL DEFAULT 0,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_run_node`(`run_id` ASC, `node_name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流水线运行日志（归档时抓下来；集群里的 Pod 随后被删）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_pipeline_run_log
-- ----------------------------

-- ----------------------------
-- Table structure for platform_rbac_template
-- ----------------------------
DROP TABLE IF EXISTS `platform_rbac_template`;
CREATE TABLE `platform_rbac_template`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模板名（裸名，K8s ClusterRole 名 = tn-tpl- + name）',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `rules` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '权限规则 JSON',
  `built_in` tinyint NOT NULL DEFAULT 0 COMMENT '是否内置：0 否，1 是（内置不可修改/删除）',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '软删除时间，NULL = 未删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_name_deleted`(`name` ASC, `deleted_at` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RBAC 模板（ClusterRole 规则集）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_rbac_template
-- ----------------------------

-- ----------------------------
-- Table structure for platform_registry_project
-- ----------------------------
DROP TABLE IF EXISTS `platform_registry_project`;
CREATE TABLE `platform_registry_project`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ULIDGenerator',
  `cluster_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'NULL = 平台共享项目（platform）',
  `host` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Harbor 访问地址（host[:port]，不带 scheme）',
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `credential_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'platform_credential.id（source=HARBOR）',
  `robot_id` bigint NULL DEFAULT NULL COMMENT 'Harbor 机器人账号 id（重建时按它删）',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'READY' COMMENT 'READY / ERROR',
  `message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `last_synced_at` datetime NULL DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_registry_project`(`cluster_id` ASC, `project_name` ASC) USING BTREE,
  INDEX `idx_registry_project_tenant`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '租户在某个 Harbor 上的镜像项目台账' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of platform_registry_project
-- ----------------------------

-- ----------------------------
-- Table structure for platform_role
-- ----------------------------
DROP TABLE IF EXISTS `platform_role`;
CREATE TABLE `platform_role`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `status` tinyint NULL DEFAULT 1,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime NULL DEFAULT NULL COMMENT '软删除时间，NULL = 未删除',
  `scope` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PLATFORM' COMMENT '角色族：PLATFORM/TENANT',
  `built_in` tinyint NOT NULL DEFAULT 0 COMMENT '内置角色：不可删除、code/scope 不可改',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of platform_role
-- ----------------------------

